contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        // Setup: record the initial ether held by c and the caller's recorded balance
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        // Make a payable Put for this test contract
        c.Put{value: putAmount}(unlockTime);

        // Read the post-Put state through the public getter
        (uint afterPutUnlock, uint afterPutBalance) = c.Acc(address(this));

        // Try the Collect. Only an external call, so wrap it in a try/catch to observe success/failure.
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read final state
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint finalContractBalance = address(c).balance;

        // If the collect did not revert and the amount was validly withdrawable, then:
        // * the final recorded balance is exactly the pre-collect balance minus the amount
        // * the contract's ether decreased by exactly the amount
        if (!collectReverted && afterPutBalance >= collectAmount && finalBalance < afterPutBalance) {
            assert(finalBalance == afterPutBalance - collectAmount);
            assert(finalContractBalance == beforeContractBalance + putAmount - collectAmount);
        } else {
            // No state-changing collect occurred: balances must be unchanged
            assert(finalBalance == afterPutBalance);
            assert(finalContractBalance == beforeContractBalance + putAmount);
        }
    }

    receive() external payable {}
}

