        c.Put{value: putAmount}(unlockTime);

        // Read post-Put state through the public getter.
        (uint afterPutUnlock, uint afterPutBalance) = c.Acc(address(this));

        // Attempt Collect; the try/catch only observes revert status, it does not nest the state-changing call.
        bool collectReverted;
        try c.Collect(collectAmount) {
