            collectReverted = true;
        }

        // Read final state through the public surface.
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint finalContractBalance = address(c).balance;

        // General rule: a successful Collect subtracts exactly the collected amount from both the caller's
