                ? finalBalance + collectAmount == afterPutBalance && finalContractBalance + collectAmount == beforeContractBalance + putAmount
                : finalBalance == afterPutBalance && finalContractBalance == beforeContractBalance + putAmount
        );
    }

    receive() external payable {}
}

